BEGIN;
CREATE TABLE operations(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),target_device_id uuid NOT NULL,type text NOT NULL CHECK(type IN('endpoint.runtime_info.v1')),arguments jsonb NOT NULL DEFAULT '{}' CHECK(arguments='{}'::jsonb),status text NOT NULL DEFAULT 'queued' CHECK(status IN('queued','ready','succeeded','failed','expired')),idempotency_key text NOT NULL CHECK(length(idempotency_key) BETWEEN 8 AND 128),expires_at timestamptz NOT NULL,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz,UNIQUE(tenant_id,idempotency_key),FOREIGN KEY(tenant_id,target_device_id) REFERENCES device_identities(tenant_id,id),CHECK(expires_at>created_at)
);
CREATE TABLE operation_outbox(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants(id),operation_id uuid NOT NULL UNIQUE REFERENCES operations(id),available_at timestamptz NOT NULL DEFAULT now(),attempts integer NOT NULL DEFAULT 0,lease_owner text,lease_until timestamptz,delivered_at timestamptz);
CREATE TABLE operation_results(operation_id uuid PRIMARY KEY REFERENCES operations(id),tenant_id uuid NOT NULL REFERENCES tenants(id),device_id uuid NOT NULL,result jsonb NOT NULL,observed_at timestamptz NOT NULL,received_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,device_id) REFERENCES device_identities(tenant_id,id));
CREATE TABLE device_heartbeats(device_id uuid PRIMARY KEY REFERENCES device_identities(id),tenant_id uuid NOT NULL REFERENCES tenants(id),observed_at timestamptz NOT NULL,received_at timestamptz NOT NULL DEFAULT now(),agent_version text NOT NULL CHECK(length(agent_version) BETWEEN 1 AND 40),FOREIGN KEY(tenant_id,device_id) REFERENCES device_identities(tenant_id,id));
ALTER TABLE operations ENABLE ROW LEVEL SECURITY;ALTER TABLE operations FORCE ROW LEVEL SECURITY;ALTER TABLE operation_outbox ENABLE ROW LEVEL SECURITY;ALTER TABLE operation_outbox FORCE ROW LEVEL SECURITY;ALTER TABLE operation_results ENABLE ROW LEVEL SECURITY;ALTER TABLE operation_results FORCE ROW LEVEL SECURITY;ALTER TABLE device_heartbeats ENABLE ROW LEVEL SECURITY;ALTER TABLE device_heartbeats FORCE ROW LEVEL SECURITY;
CREATE POLICY operations_scope ON operations USING(tenant_id::text=current_setting('app.tenant_id',true) OR target_device_id::text=current_setting('app.device_id',true) OR current_setting('app.worker_role',true)='operation_dispatch');
CREATE POLICY outbox_scope ON operation_outbox USING(tenant_id::text=current_setting('app.tenant_id',true) OR operation_id IN(SELECT id FROM operations) OR current_setting('app.worker_role',true)='operation_dispatch');
CREATE POLICY results_scope ON operation_results USING(tenant_id::text=current_setting('app.tenant_id',true) OR device_id::text=current_setting('app.device_id',true));
CREATE POLICY heartbeats_scope ON device_heartbeats USING(tenant_id::text=current_setting('app.tenant_id',true) OR device_id::text=current_setting('app.device_id',true));
CREATE INDEX operations_target_status_idx ON operations(target_device_id,status,created_at);CREATE INDEX outbox_claim_idx ON operation_outbox(available_at,lease_until) WHERE delivered_at IS NULL;
COMMIT;
